from common import *
def main():
    verify();qual=json.loads((R/'QUALIFICATION.json').read_text());snap=json.loads((R/'INPUT_SNAPSHOT.json').read_text());drift=[p for p,h in snap['preserved_originals'].items() if sha(LAB/p)!=h];hold=[p for p,h in snap['C16_holds'].items() if sha(Path(p))!=h];assert not drift and not hold
    results=read(R/'CALIBRATION_RESULTS.csv');assert len(results)==140;passed=sum(c['cell_pass'] for c in qual['cells']);failed=qual['status']=='FAIL'
    assert not failed or (not (R/'targets').exists() and not (R/'TARGET_RUN_MANIFEST.json').exists())
    rows=['# Phase7 add-on: convention-count qualification','',f"Calibration: **{qual['status']}**, {passed}/28 cells passed the registered operating criteria.140 datasets, five seeds per cell, both plaintexts and clean/noisy views.",'', 'The primary analysis is order-agnostic: physical conjugacy and quire coherence. Reading-order proposals are secondary, source-dependent sensitivities. Quire sizes are fixed under the coherence null, while leaf/bifolio labels move across quire slots; shuffling labels within each quire would preserve coherence exactly.','', '| Plaintext | True k | Schedule | View | Passing seeds /5 | Selected k counts | Cell pass |','|---|---:|---|---|---:|---|---|']
    for c in qual['cells']:rows.append(f"| {c['family']} | {c['true_k']} | {c['schedule']} | {c['view']} | {c['passing_seeds']} | {json.dumps(c['selected_k_counts'],sort_keys=True)} | {c['cell_pass']} |")
    if failed:rows+=['','**STOP. The calibration gate failed. No ZL/H text fingerprints, manuscript mixture fits, best k, nesting/metadata associations, physical-test outcomes or sequence results were computed.** The requested manuscript analysis remains unqualified; this is a method/control failure, not evidence about how many conventions the manuscript has. No feature/covariance/profile/threshold rescue was attempted.']
    else:rows+=['','The calibration gate passed. Target results are in TARGET_SELECTIONS.json, TARGET_PHYSICAL_TESTS.csv, TARGET_STABILITY.csv, and the targets/ per-seed likelihood, assignment, metadata and secondary-order receipts.']
    rows+=['','## Registered method and controls','', 'All declared scalar/ngram/word-length/affix/slot-grammar feature families enter a train-fold transform. Regularized tied-covariance Gaussian mixtures k1..12 are selected by leaf-grouped held-out log likelihood, not metadata or visual clustering. PCA20 plus a shared residual density is an explicit working likelihood; it does not identify literal languages or writing conventions. Full curves, convergence failures, retained variance and per-page features are retained. Controls use known2/4-table mixtures, three physical switching schedules, single-table references, identical page/leaf/bifolio/quire geometry, fixed seeds and the original noise model. True labels enter only after unsupervised k selection.','', 'Naibbe published glyph tables and slot grammar were developed using Voynich material and are NOT blind controls. C1 Latin and C2 Italian share paired versions and schedules; clean/noisy views are not independent manuscripts. Five seeds do not establish population-wide calibration.','', '## Codicology and order-source limits','', 'Physical collation and missing leaves follow [Zandbergen\'s published layout](https://www.voynich.nu/layout.html) and individual quire descriptions. Foldout panels are pooled to leaf sides; all panels and both sides stay in one leaf fold. Coverage, fixed folds and physical sheet/conjugate links are frozen in COMMON_PAGES.json, FOLDS.json and PHYSICAL.json. No original reading order is assumed.','', 'ORDER_REGISTRY.json lists current binding, the Bunn/Pelling Q20 center fragment, Pelling Q20 subgroup/adjacency suggestions, Pelling2006 Q13, Layfield/Davis2026 singulions/Q13 variant, the Q9 refolding suggestion and VoynichViews2015 Q13. Ambiguous, source-unavailable or insufficient fragments are explicitly not assigned a guessed total order. The [Layfield/Davis publisher page](https://doi.org/10.4000/16k0a) served a bot challenge; the [image resource](https://quantumlynxresearch.com/resources/singulion_images) names sheets by present nesting position, not a uniquely verified original total order. Current order and proposals would be reported separately only after qualification; no source is ranked or chosen by clusters.','', '## Receipts and preservation','', 'REGISTRATION.json predates control generation/model fitting. CONTROL_DATA_READY.json freezes every generated text/truth file before model fitting. Each dataset retains held-out likelihoods, any convergence failures, selected k, ARI, page labels, full model and primary null distributions. QUALIFICATION.json and RUN_STATE.json record the gate. Original Phase7/C12 artifacts and C16 hold files remain hash-identical. No new C12 sweep, C16 scoring or translation claim.']
    (R/'REPORT.md').write_text('\n'.join(rows)+'\n',encoding='utf8')
    dump(R/'VERIFICATION.json',dict(status='PASS',qualification=qual['status'],calibration_datasets=len(results),registered_cells=28,original_drift=drift,C16_hold_drift=hold,target_analysis_absent_on_failed_gate=failed,target_features_read=not failed,registration_sha256=sha(R/'REGISTRATION.json')))
    dump(R/'OUTPUT_HASHES.json',{p.name:sha(p) for p in R.iterdir() if p.is_file() and p.name!='OUTPUT_HASHES.json'});print('Report complete; qualification',qual['status'],passed,'/28 cells. Target access:',not failed)
if __name__=='__main__':main()
